  // --- Phrases : découpage et difficulté (partagé par le serveur et les téléphones) ---
  const TEXTS = BANK.map(([t, a, src], id) => ({ id, t, a: a || '', src: src || '' }));
  function tokens(t) {
    const out = []; let pre = '';
    for (const w of t.split(/\s+/).filter(Boolean)) {
      if (w === '«') { pre = '« '; continue; }
      if (/^[;:!?».,]+$/.test(w) && out.length) { out[out.length - 1] += ' ' + w; continue; }
      out.push(pre + w); pre = '';
    }
    return out;
  }
  const diffOf = it => { const n = tokens(it.t).length; return n <= 5 ? 1 : n <= 8 ? 2 : 3; };
  const LDIFF = { 1: 1, 2: 1, 3: 2, 4: 2, 5: 3, 6: 3 };
  const TEXT_LEVELS = { 1: 'Phrase courte, en morceaux', 2: 'Phrase courte, mot par mot', 3: 'Phrase moyenne, en morceaux', 4: 'Phrase moyenne, mot par mot', 5: 'Phrase longue, en morceaux', 6: 'Phrase longue, mot par mot' };
  function frags(it, level) {
    const w = tokens(it.t);
    if (level % 2 === 0) return w;
    const k = { 1: 3, 3: 4, 5: 5 }[level], size = Math.ceil(w.length / k), out = [];
    for (let i = 0; i < w.length; i += size) out.push(w.slice(i, i + size).join(' '));
    return out;
  }
  function shuffle(a, rnd) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
  // Tire 5 phrases du bon niveau, jamais déjà vues par ce groupe tant qu'il en reste.
  function pickTexts(level, seen, rnd) {
    const d = LDIFF[level], ofD = TEXTS.filter(x => diffOf(x) === d);
    let pool = ofD.filter(x => !seen.has(x.id));
    if (pool.length < 5) { ofD.forEach(x => seen.delete(x.id)); pool = ofD.slice(); }
    pool = shuffle(pool.slice(), rnd).slice(0, 5);
    if (pool.length < 5) pool = pool.concat(shuffle(TEXTS.filter(x => !pool.includes(x) && Math.abs(diffOf(x) - d) === 1), rnd).slice(0, 5 - pool.length));
    if (!pool.some(x => x.a)) { const c = shuffle(TEXTS.filter(x => x.a && diffOf(x) === d && !pool.includes(x)), rnd)[0]; if (c) pool[4] = c; }
    pool.forEach(x => seen.add(x.id));
    return pool.map(x => x.id);
  }
  // Question bonus fabriquée à partir des phrases jouées.
  function textQuiz(ids, rnd) {
    const items = ids.map(i => TEXTS[i]), withA = items.filter(x => x.a);
    if (withA.length) {
      const x = withA[Math.floor(rnd() * withA.length)];
      const others = shuffle([...new Set(TEXTS.filter(y => y.a && y.a !== x.a).map(y => y.a))], rnd).slice(0, 2);
      const options = shuffle([x.a, ...others], rnd);
      return { q: `Qui a écrit « ${x.t.replace(/[\s\u00a0]*[.!?]$/, '')} » ?`, options, answer: options.indexOf(x.a) };
    }
    const x = items[0], w = tokens(x.t), last = w[w.length - 1];
    const others = shuffle([...new Set(TEXTS.filter(y => y !== x).map(y => { const z = tokens(y.t); return z[z.length - 1]; }))].filter(z => z !== last), rnd).slice(0, 2);
    const options = shuffle([last, ...others], rnd);
    return { q: `Complétez : « ${w.slice(0, -1).join(' ')} … »`, options, answer: options.indexOf(last) };
  }
