  // ---------- Calcul : remettre nombres et signes dans un calcul juste ----------
  function rngC(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
  const CALC_CFG = {
    1: { terms: 2, max: 9, ops: ['+'], extraN: 0, extraOp: 0 },
    2: { terms: 2, max: 20, ops: ['+', '-'], extraN: 0, extraOp: 1 },
    3: { terms: 3, max: 20, ops: ['+', '-'], extraN: 0, extraOp: 0 },
    4: { terms: 3, max: 50, ops: ['+', '-'], extraN: 1, extraOp: 1 },
    5: { terms: 4, max: 50, ops: ['+', '-'], extraN: 1, extraOp: 1 },
    6: { terms: 4, max: 99, ops: ['+', '-'], extraN: 2, extraOp: 2 }
  };
  const CALC_LEVELS = { 1: 'Une addition simple', 2: 'Plus ou moins, jusqu’à 20', 3: 'Trois nombres, jusqu’à 20', 4: 'Trois nombres, jusqu’à 50, un intrus', 5: 'Quatre nombres, un intrus', 6: 'Quatre nombres jusqu’à 99, des intrus' };
  const evalOps = (nums, ops) => nums.slice(1).reduce((acc, n, i) => ops[i] === '+' ? acc + n : acc - n, nums[0]);
  const sign = o => o === '-' ? '−' : o;
  function calcRound(level, seed) {
    const c = CALC_CFG[level], R = rngC(seed), r = n => 1 + Math.floor(R() * n);
    let nums, ops, res;
    for (let k = 0; k < 500; k++) {
      nums = Array.from({ length: c.terms }, () => r(c.max));
      ops = Array.from({ length: c.terms - 1 }, () => c.ops[Math.floor(R() * c.ops.length)]);
      res = evalOps(nums, ops);
      const run = nums.map((_, i) => evalOps(nums.slice(0, i + 1), ops)); if (run.every(v => v >= 0) && res <= c.max * 2 && new Set([...nums, res]).size === c.terms + 1) break;
    }
    const tiles = [...nums, res].map(v => ({ k: 'n', v }))
      .concat(ops.map(v => ({ k: 'o', v })))
      .concat(Array.from({ length: c.extraN }, () => ({ k: 'n', v: r(c.max) })))
      .concat(Array.from({ length: c.extraOp }, () => ({ k: 'o', v: c.ops[Math.floor(R() * c.ops.length)] })));
    for (let i = tiles.length - 1; i > 0; i--) { const j = Math.floor(R() * (i + 1)); [tiles[i], tiles[j]] = [tiles[j], tiles[i]]; }
    // cases : n o n (o n …) = n   (le signe « = » est déjà posé)
    const slots = []; for (let i = 0; i < c.terms; i++) { if (i) slots.push('o'); slots.push('n'); } slots.push('n');
    return { nums, ops, res, tiles, slots, text: nums.map((n, i) => (i ? sign(ops[i - 1]) + ' ' : '') + n).join(' ') + ' = ' + res };
  }
  // Une rangée remplie : n o n … n  → juste ?
  function calcCheck(slots, vals) {
    const left = vals.slice(0, -1), nums = left.filter((_, i) => i % 2 === 0), ops = left.filter((_, i) => i % 2 === 1);
    return evalOps(nums, ops) === vals[vals.length - 1];
  }
  function calcQuiz(level, seeds, rnd) {
    const rd = calcRound(level, seeds[Math.floor(rnd() * seeds.length)]);
    const a = rd.nums[0], b = rd.nums[1], op = rd.ops[0], good = op === '+' ? a + b : a - b;
    const set = new Set([good]); while (set.size < 3) { const d = good + (rnd() < .5 ? -1 : 1) * (1 + Math.floor(rnd() * 10)); if (d >= 0) set.add(d); }
    const options = shuffle([...set], rnd).map(String);
    return { q: `De tête : combien font ${a} ${sign(op)} ${b} ?`, options, answer: options.indexOf(String(good)) };
  }
  THEMES.calcul = { kind: 'calc', cat: 'calcul', name: 'Calcul malin', desc: 'Remettez nombres et signes dans un calcul juste' };

